import{_ as i,o as n,c as a,a5 as e}from"./chunks/framework.CsGesDJn.js";const k=JSON.parse('{"title":"Giai đoạn 1 — Task Detail, Assignment và Comments","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/task-workflow-phase-1.md","filePath":"feature/content-task-workflow/task-workflow-phase-1.md"}'),s={name:"feature/content-task-workflow/task-workflow-phase-1.md"};function o(h,t,r,l,c,d){return n(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="giai-đoan-1-—-task-detail-assignment-va-comments" tabindex="-1">Giai đoạn 1 — Task Detail, Assignment và Comments <a class="header-anchor" href="#giai-đoan-1-—-task-detail-assignment-va-comments" aria-label="Permalink to &quot;Giai đoạn 1 — Task Detail, Assignment và Comments&quot;">​</a></h1><p>Ngày 2026-10-14. DA-978 / DA-E51-04 (FR 3.6.1/2), DA-1236 / DA-E51-04b (FR 3.6.3).</p><h2 id="ket-qua-va-gioi-han" tabindex="-1">Kết quả và giới hạn <a class="header-anchor" href="#ket-qua-va-gioi-han" aria-label="Permalink to &quot;Kết quả và giới hạn&quot;">​</a></h2><ul><li>BA mới nhất Q13 confirmed 2026-10-14: Client active xem/bình luận mọi Task cùng Workspace, kể cả Task Manager tạo thủ công và Task cũ. Bỏ phân biệt nội bộ/thường, field/default/index hiển thị và validation Q12. requiresClientApproval chỉ cấu hình duyệt kết quả; notification Q11 giữ nguyên.</li><li>Q8 giữ nguyên: <strong>Creator bấm Bắt đầu làm</strong>, không tự start khi mở editor. Legacy thiếu lịch sử start/revision cần review trước mutation quản lý, không chặn đọc/bình luận theo membership.</li><li>Mỗi FR có spec → plan → task → test; <a href="./task-workflow-contract.html">contract chung</a> chứa API mục tiêu, ma trận quyền, lifecycle/CAS, private upload/outbox và ranh giới module.</li><li>Viết migration foundation additive, fresh init Mongo, checker và regression tests.</li><li><strong>Chưa triển khai API/UI/worker</strong>. Không đánh dấu FR hoặc Jira Done bằng kết quả schema tests.</li><li>Không chạy migration trên Atlas/PostgreSQL đang dùng, không seed/backfill/xóa dữ liệu người dùng.</li><li>Một test Business mới là tooling inventory <strong>opt-in, chỉ đọc</strong>, không load Spring context/seeders.</li></ul><h2 id="baseline-va-đong-bo-infrastructure" tabindex="-1">Baseline và đồng bộ Infrastructure <a class="header-anchor" href="#baseline-va-đong-bo-infrastructure" aria-label="Permalink to &quot;Baseline và đồng bộ Infrastructure&quot;">​</a></h2><p>Business <code>ecfdd84</code>, Web <code>b63b3a9</code>, Gateway <code>0364426</code>; chưa đổi code ứng dụng trong phase1. Infrastructure merge <code>156e2c2</code>, gộp origin/develop <code>3f6689d</code> (15 commit mới), không conflict. Stash đúng các tài liệu Task rồi apply lại thành công; giữ backup <code>phase-1-task-docs-before-develop-sync-20261014</code>, không drop/pop/push. Branch Infrastructure <code>docs/media-workflow-phase-1</code>; không code trên develop.</p><h2 id="inventory-that-—-chi-đoc" tabindex="-1">Inventory thật — chỉ đọc <a class="header-anchor" href="#inventory-that-—-chi-đoc" aria-label="Permalink to &quot;Inventory thật — chỉ đọc&quot;">​</a></h2><p>Chạy hai opt-in tests <code>ContentRequestAtlasInventoryTest</code> và <code>TaskWorkflowAtlasInventoryTest</code>, chỉ aggregate/count/list metadata, URI lấy trong môi trường cấu hình nhưng không in/log ra ngoài. Kết quả là snapshot lúc kiểm tra, không phải dữ liệu seed hay cam kết DB không đổi sau đó.</p><table tabindex="0"><thead><tr><th>Kiểm tra brandhub</th><th>Kết quả</th></tr></thead><tbody><tr><td>Topology</td><td>Replica set + sessions, maxWireVersion 25</td></tr><tr><td>Task tổng</td><td>8, tất cả BACKLOG</td></tr><tr><td>Task CAMPAIGN</td><td>4 POST</td></tr><tr><td>Task CONTENT_REQUEST</td><td>1 POST + 1 SURVEY</td></tr><tr><td>Task thiếu sourceType</td><td>2 POST, không tự suy nguồn để backfill</td></tr><tr><td>Thiếu workflowRevision/firstStartedAt</td><td>8 / 8</td></tr><tr><td>Task ASSIGNED thiếu lịch sử start</td><td>0 tại snapshot; không suy dữ liệu tương lai an toàn</td></tr><tr><td>Request Task chưa gắn Campaign</td><td>1; cần reconcile riêng trước closure Workspace tương ứng</td></tr><tr><td>task_approvals</td><td>Có collection/index, 0 documents</td></tr><tr><td>Comments/uploads/outbox</td><td>Chưa có ba collection mới</td></tr><tr><td>Content Request</td><td>3: 1 IN_PROGRESS, 2 ACCEPTED</td></tr><tr><td>Unique source indexes</td><td>Có Campaign work item và Content Request; không trùng Request source</td></tr><tr><td>Task cancellation schema</td><td><strong>Chưa có CANCELLED và cancellation audit</strong></td></tr></tbody></table><p>Vì thiếu closure schema, foundation mới <strong>chủ động từ chối</strong> chạy trước dependency. Không tự gán start marker cho 8 Task cũ. Không có thao tác tự gắn Campaign cho Request Task cũ. Inventory là snapshot trước Q13; quyền đọc/bình luận mới không cần backfill hay marker hiển thị. Playground inventory để thành viên kiểm tra lại: <a href="../../database/migrations/task-workflow-inventory.mongodb.js">task-workflow-inventory.mongodb.js</a>.</p><h2 id="inventory-writers-va-hop-đong-khong-đuoc-pha" tabindex="-1">Inventory writers và hợp đồng không được phá <a class="header-anchor" href="#inventory-writers-va-hop-đong-khong-đuoc-pha" aria-label="Permalink to &quot;Inventory writers và hợp đồng không được phá&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Writer hiện tại (Business)</th><th>Dữ liệu/đặc điểm phải giữ</th><th>Bổ sung về sau</th></tr></thead><tbody><tr><td>CampaignTaskStore</td><td>ID deterministic theo Campaign/work item; sourceRefId=workItem ID</td><td>revision=0, marker null; đọc/bình luận theo WS</td></tr><tr><td>ContentRequestTaskStore</td><td>Request source unique, BACKLOG; campaign hiện tại, workItem=null</td><td>revision=0, marker null; đọc/bình luận theo WS</td></tr><tr><td>TaskServiceImpl</td><td>Editor tạo POST tối giản, Mongo identity; legacy SQL content/history còn dùng</td><td>Metadata revision/start; không đổi quyền/editor auto-create; Client đọc/bình luận theo WS</td></tr><tr><td>CampaignClosureService / cancellation store</td><td>Agreement lock; CAS status+updatedAt, cancellation audit</td><td>Cùng contract revision, không phục hồi CANCELLED</td></tr><tr><td>E51-03 Approval</td><td>approvalRound/history/submit/reject thuộc chủ module</td><td>Review first-start/CAS và duyệt lại QC ở lượt mới</td></tr></tbody></table><p>Phối hợp E51-05 list endpoint/entry point, E51-03 start/resubmit trước code tích hợp. Chưa tự liên hệ/đổi Jira hoặc sửa code Approval/editor của thành viên khác.</p><h2 id="migration-va-setup-khi-đen-đot-rollout" tabindex="-1">Migration và setup khi đến đợt rollout <a class="header-anchor" href="#migration-va-setup-khi-đen-đot-rollout" aria-label="Permalink to &quot;Migration và setup khi đến đợt rollout&quot;">​</a></h2><p>File: <a href="../../database/migrations/2026-10-14-task-detail-comments-foundation.js">2026-10-14-task-detail-comments-foundation.js</a>.</p><ol><li>Backup có thể phục hồi, xác nhận connection/database brandhub và tạm dừng writers.</li><li>Chạy checker chỉ đọc; nếu closure schema thiếu, review và áp <strong>đúng</strong><code>2026-10-14-campaign-closure.js</code> theo <a href="./../../database/mongo-atlas-migrations.html">hướng dẫn Atlas</a>. Review <code>unlinkedRequestTasks</code>; không tự sửa/xóa để làm preflight xanh.</li><li>Run All foundation với <code>globalThis.TASK_WORKFLOW_FOUNDATION_APPLY = false</code>. Script luôn chọn brandhub, kiểm validator/index xung đột, document không hợp lệ và duplicate unique keys trước mọi DDL. <code>blocked=true</code> hoặc exception → dừng review, không xóa dữ liệu/field/index tự động.</li><li>Chỉ khi operator đã duyệt preflight: đặt flag true trong cùng Playground run với toàn bộ script. Kết thúc đặt flag false, không để APPLY=true cho lần chạy sau. Đây là hướng dẫn, <strong>chưa thực hiện trên Atlas</strong>.</li><li>Chạy checker: <code>schemaChecks.taskWorkflowFoundation=true</code>; inventory số documents không thay đổi. Thiếu Mail/Chat/Post Versions không tự rerun toàn bộ migration Task cũ vì có thể ghi đè validator mới.</li><li>DDL nhiều collection không cùng transaction: nếu có lỗi vận hành sau khi bắt đầu DDL, giữ feature disabled, kiểm metadata và chạy lại an toàn. Không drop collections/indexes để rollback.</li><li>Khi triển khai ứng dụng mới, kiểm ACL/defaults/legacy review/start/transactions trước khi bật tính năng; schema MATCH không phải chứng minh permission hoặc API đã hoạt động.</li></ol><p>Foundation chỉ thêm optional fields vào tasks và tạo ba collection riêng; không thêm required cho Task cũ. Không xóa TTL/index cũ hoặc task_approvals; không thay typeMetadata/approved Campaign plan. Draft foundation chưa commit/merge và chưa được agent áp lên Atlas nên chỉnh trực tiếp draft để bỏ field/index hiển thị. Nếu môi trường khác đã tự áp draft trước Q13: không tự drop field/index hoặc xóa documents; kiểm inventory và review riêng. Metadata dư không được dùng làm gate quyền trong ứng dụng mới. SQL inbox <code>user_notifications</code> hiện có đã đủ; không tạo migration PostgreSQL cho ba FR này.</p><h2 id="đong-bo-init-va-phan-ngoai-pham-vi" tabindex="-1">Đồng bộ init và phần ngoài phạm vi <a class="header-anchor" href="#đong-bo-init-va-phan-ngoai-pham-vi" aria-label="Permalink to &quot;Đồng bộ init và phần ngoài phạm vi&quot;">​</a></h2><p><code>init-mongo.js</code> fresh-only hiện có 24 collections, khớp 11 migration effects (gồm hai Mail Mongo migration vừa merge). Mail validators/indexes được sao đúng từ migration, không sửa các migration đã merge. Không chạy init lên Atlas hoặc database đang có dữ liệu.</p><p>Phát hiện riêng: upstream <code>2026-10-12-create-mail-sending-tables.sql</code> chưa được fold vào <code>init-postgres-v2.sql</code>. Đây là thiếu đồng bộ <strong>Mail của develop</strong>, không phải schema Task cần thêm; giữ ngoài đợt sửa Task này để người phụ trách review. Môi trường PostgreSQL mới cần chạy Mail migration riêng nếu test Mail; không tuyên bố init PostgreSQL đã cover mọi thay đổi upstream.</p><h2 id="kiem-chung" tabindex="-1">Kiểm chứng <a class="header-anchor" href="#kiem-chung" aria-label="Permalink to &quot;Kiểm chứng&quot;">​</a></h2><p>Offline, không kết nối DB:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">node </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">test </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">test-isolation</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">none docs</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">database</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">migrations</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tests</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">check</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mongo</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">migrations.test.cjs docs</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">database</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">migrations</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tests</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">content</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">requests</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">v2.test.cjs docs</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">database</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">migrations</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tests</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">content</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">request-acceptance</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.test.cjs</span></span></code></pre></div><p><strong>34/34 pass (sau Q13)</strong>: checker read-only, init/cumulative validator/index parity, dependency guards, DRY_RUN/APPLY/repeat, bảo toàn required/unknown fields/root clauses/indexes, xung đột trước mọi DDL, invalid legacy/duplicate blocking, upload không TTL, Request V2/acceptance regression và inventory utility. Q13 thêm case schema mới không có field/index hiển thị, và không drop metadata dư nếu operator từng áp draft cũ ở môi trường khác. Đây không phải test API authorization; API/UI còn chưa triển khai.</p><p>MongoDB thật <strong>7 local cô lập</strong>, không network/host port và không dùng volume dữ liệu người dùng: test <a href="../../database/migrations/tests/task-workflow-foundation.integration.js">task-workflow-foundation.integration.js</a>. Pass DRY_RUN/APPLY/repeat, legacy no-backfill/old writer compatibility, enums/revision/date validation, 5MB WebP boundary, MIME/size reject, unique comment/outbox, preflight invalid data/late conflict; checker thật đạt <strong>11 MATCH, 0 MISSING/DRIFT/UNKNOWN</strong>. Đã chạy lại sau Q13, xác nhận không tạo field/index hiển thị và Task thủ công vẫn lưu requiresClientApproval=true độc lập nguồn. Đây là schema test, không phải Task API/Mongo transaction/S3 integration hoặc test trên Mongo Atlas 8.x.</p><p>Test destructive chỉ được chạy trong container mới, DB brandhub trống, có đủ ba guard: loopback URI + <code>BRANDHUB_SCHEMA_TEST_CONTAINER=1</code> + <code>BRANDHUB_ISOLATED_SCHEMA_TEST=true</code>. Mount thư mục database read-only tại <code>/schema</code>; tuyệt đối không chạy file integration trên shared DB.</p><p>Business test inventory opt-in đã compile lại sau khi bỏ count của field hiển thị. Lần kiểm compile này không đặt BRANDHUB_MONGO_INVENTORY_URI nên test được skip đúng guard, không kết nối DB thật.</p><p>Các test ứng dụng trong test.md vẫn <strong>Chưa test</strong>. Phase tiếp: nền API đọc workflow/ACL/Task Detail; assignment/start và comments theo các giai đoạn tiếp theo, không lấy schema tests thay nghiệm thu FR.</p>',28)])])}const p=i(s,[["render",o]]);export{k as __pageData,p as default};
